const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const file = path.join(os.tmpdir(), `counter-${process.pid}.js`);
fs.writeFileSync(file, "console.log('loading counter');\nlet n = 0;\nmodule.exports = { inc: () => ++n };");
const a = require(file);
const b = require(file);
console.log(a === b, a.inc(), b.inc());
delete require.cache[require.resolve(file)];
const c = require(file);
console.log(c === a, c.inc());
fs.unlinkSync(file);

